<?php use Luna\Core\Csrf; use Luna\Core\View; ?>
<section class="card form-card"><div class="card-header"><div><h2>Nuovo import DATEV Koinos</h2><p class="muted">Il file viene prima caricato in staging. Nessun dato operativo cambia fino alla conferma.</p></div></div><form method="post" action="/imports/upload" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><label><span>Tipo dati *</span><select name="import_type" required><option value="customers">Clienti</option><option value="suppliers">Fornitori</option><option value="chart_of_accounts">Piano dei conti</option><option value="journal_entries">Prima nota / movimenti</option><option value="open_items">Partite aperte / scadenzario</option><option value="payments">Pagamenti e incassi storici</option><option value="vat_movements">Registri IVA storici</option><option value="fixed_assets">Cespiti</option><option value="bank_transactions">Movimenti bancari</option><option value="fatturapa">Fatture XML FatturaPA</option></select></label><label><span>File *</span><input type="file" name="import_file" accept=".csv,.txt,.xlsx,.xml,.p7m,.zip" required></label><div class="full-width"><button class="button primary" type="submit">Carica e analizza</button></div></form><p class="help">Accettati CSV/XLSX, XML FatturaPA e ZIP. Importare nell’ordine: piano dei conti, anagrafiche, prima nota, registri IVA, partite/pagamenti, cespiti e banca. Gli export Koinos possono richiedere l’adattamento delle intestazioni dopo l’anteprima.</p></section>
<section class="card table-wrap"><table><thead><tr><th>#</th><th>Data</th><th>File</th><th>Tipo</th><th>Stato</th><th>Righe</th><th>Importate</th><th>Errori</th></tr></thead><tbody><?php foreach ($batches as $batch): ?><tr><td><a href="/imports/<?= (int) $batch['id'] ?>">#<?= (int) $batch['id'] ?></a></td><td><?= View::date($batch['created_at']) ?></td><td><?= View::e($batch['original_filename']) ?></td><td><?= View::e($batch['import_type']) ?></td><td><span class="badge"><?= View::e($batch['status']) ?></span></td><td><?= (int) $batch['total_rows'] ?></td><td><?= (int) $batch['imported_rows'] ?></td><td><?= (int) $batch['error_rows'] ?></td></tr><?php endforeach; ?><?php if (!$batches): ?><tr><td colspan="8" class="muted">Nessuna importazione.</td></tr><?php endif; ?></tbody></table></section>
